#ifndef P4_BOARD_OTA_CLIENT_H
#define P4_BOARD_OTA_CLIENT_H
#include "../network/owner_ota_queue.h"

/* Single submitting task only. Storage, callback context and snapshots must
 * not overlap request/image or each other. No request pointer is retained.
 * Prepared gates are caller attestations, not generated by this client. */
struct board_ota_client_ops {
    uint32_t (*submit)(void *, const struct p4_wifi_ota_request *);
    enum p4_wifi_ota_job_state (*poll)(void *, uint32_t,
        struct p4_wifi_ota_observation *);
    int (*cancel)(void *, uint32_t);
    int (*discard)(void *, uint32_t);
};
enum board_ota_client_phase {
    BOARD_OTA_CLIENT_IDLE = 0, BOARD_OTA_CLIENT_REFUSED,
    BOARD_OTA_CLIENT_PENDING, BOARD_OTA_CLIENT_DISCARDING,
    BOARD_OTA_CLIENT_FINISHED
};
struct board_ota_client {
    struct board_ota_client_ops ops;
    void *context;
    enum board_ota_client_phase phase;
    uint32_t token, generation, image_size, acknowledged_bytes;
    uint8_t cancel_requested, cancel_accepted, observation_unconfirmed;
    uint8_t saw_running;
    struct p4_wifi_ota_observation terminal;
};
/* Initialize once before start. Refused submission is terminal: never replay
 * automatically, including on metadata contention or an unknown observation. */
void board_ota_client_init(struct board_ota_client *);
int board_ota_client_start(struct board_ota_client *,
    const struct board_ota_client_ops *, void *,
    const struct p4_wifi_ota_request *);
/* One nonblocking metadata step. Cancel is sticky. The caller MUST survive
 * PENDING/DISCARDING, even after clock failure, Close or timeout: those are
 * cancel reasons, not evidence of job completion. Only REFUSED/FINISHED may
 * release requester storage. FINISHED does not mean installed or recovered.
 * No wait, transport, clock renewal, reset or postboot confirmation occurs. */
enum board_ota_client_phase board_ota_client_step(struct board_ota_client *,
    int cancel_requested);
#endif
